from pathlib import Path
import sqlite3,json,re
w=Path(__file__).resolve().parent;c=sqlite3.connect('file:'+str(w/'input/index.sqlite3')+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
lookup={}
for row in sorted(c.execute("SELECT * FROM segments WHERE path LIKE 'input/sources/%'"),key=lambda x:x['method']=='manual-transcription'):
 d=dict(row)
 for m in re.findall(r'\[([A-Z]+[0-9]+)\]',d['quote']):lookup[m]=d
reports=json.loads((w/'input/report-ledger.json').read_text())
def ev(m):
 d=lookup[m];l=json.loads(d['locator']);src=d['path'].removeprefix('input/');src=src[:-3] if src.endswith('.pdf.md') else src
 return {'path':d['path'],'anchor':d['anchor'],'quote':d['quote'],'source_marker':m,'original_source_file':src,'original_coordinate':{k:v for k,v in l.items() if k in ('original','original_sha256','page','line_start','line_end')}}
def pr(t,target,rel='supports'):return {'module':'Audit','theorem':'Audit.'+t,'relation':rel,'target':target}
f=[]
def add(i,q,markers,rules,reason,formal,proofs,limits,reco,assumptions=None):
 k=f'C08-OK-{i:02d}';f.append({'claim_id':k,'report_anchor':k,'report_quote':reports[k],'question':q,'evidence':[ev(m) for m in markers],'rules':rules,'assumptions':assumptions if assumptions is not None else ['Use the supplied synthetic day, lot identities and exact individual-unit conversions. Accept the explicitly complete A/B movement journal only for its named boundary and interval.','The legible material scan fields were actually viewed and corroborated; manual reviewed anchors preserve original-source hashes and raw OCR. No real handwriting authentication or external event inspection is claimed.'],'reasoning':[str(j+1)+'. '+x for j,x in enumerate(reason)],'semantic_state':'supported','argument_status':'sufficient','formal_status':formal,'proofs':proofs,'limits':limits,'recommendation':reco})
add(1,'Did the accepted Lot A inbound movement contain exactly96 individual units?', ['T01','R01','R02','J01','K01'],['R01 assigns twelve units to a sealed full crate. R02 counts accepted custody, not an expected order; K01 authorizes Elin to receive.'],['Visually inspected T01 records eight sealed full A crates accepted by Elin at09:00, with no partial/damaged/empty override. J01 independently records the posted accepted receipt.','Eight times twelve gives96 units, preserving crate factor and lotA identity.','The source proves a completed inbound movement within this synthetic journal, not mere planned procurement.'],'proved',[pr('claim01','Audit.inboundA = 96')],['The result concerns this named accepted movement only, not all physical stock or unrelated lotD.'],'Retain the96-unit accepted inbound finding and original scan marker T01.')
add(2,'Did the accepted Lot B inbound movement contain exactly12 units, using carton rather than crate conversion?', ['T02','R01','J01','K01'],['A sealed full carton is six units under R01; lot identity and container type control.'],['T02 visually records two sealed full B cartons accepted by Elin, confirmed by J01; no partial override appears.','Two times six equals12. Applying twelve-unit crate conversion would misread the source container type.'],'proved',[pr('claim02','Audit.inboundB = 12')],['This receipt is distinct from the separate eight-unit next-day reservation.'],'Retain12 accepted B units and identify the six-unit carton factor.')
add(3,'Does the complete A movement journal produce148 book on-hand units at18:00 on April14?', ['R02','R04','J01','J02','K03','BIN01','T01','T03'],['Book on-hand is opening plus accepted inbound minus actual departure plus accepted return. K03/R04 bound movement completeness to A/B that day; cage acceptance is inside the boundary.'],['A opens100, accepts96 inbound, departs60 in five full crates, then separately accepts12 returned units inside the fenced cage before cutoff.','The signed ledger calculation100+96-60+12 equals148. The original five-crate departure is retained rather than erased when one crate returns.','Internal gate-to-shelf/cage movement creates no second receipt, and quarantine creates no departure. The report is explicitly a book result.'],'proved',[pr('claim03','Audit.bookA = 148')],['A physical counts separately conflict at148 and147; agreement with one observation does not resolve or override the other.'],'Retain148 as book on-hand and display the physical-count discrepancy separately.')
add(4,'Is A available book stock141 after the separately specified quarantine deduction from book on-hand148?', ['R03','J02','BIN02','J01','K03'],['R03 availability subtracts quarantined and separately reserved quantities without overlap; quarantine does not transfer custody.'],['The complete movement arithmetic gives A book148. J02/BIN02 identify exactly seven loose A units quarantined onW1 shelf, still inside the boundary and not released before cutoff.','The applicable A status schedule deducts seven units, giving148-7=141 available book stock.','The deduction is individual units, not seven crates, and does not reduce book on-hand itself.'],'proved',[pr('claim04','Audit.availableA = 141')],['This is book-derived availability under the supplied deduction schedule; it does not settle the disputed physical total.'],'Retain141 available and keep148 book and seven quarantined as distinct fields.',['R03 and the supplied bin tickets are interpreted as the applicable finite A/B deduction schedule; no undocumented extra holds or reservations are invented.'])
add(5,'Does B book on-hand remain40 after its accepted receipt, actual two-carton departure and canceled unfilled request?', ['R01','R02','J01','J03','T02','T04','K03'],['Actual signed handoff controls movement under R02/R04. A canceled requested quantity that never departed is neither a departure nor return.'],['B opens40, receives two full cartons=12, and actually hands over two full cartons=12; J03 records no return or other B movement.','The third requested carton stayed on the shelf. Its cancellation requires no invented12/6-unit return or subtraction.','Book calculation40+12-12+0 equals40.'],'proved',[pr('claim05','Audit.bookB = 40')],['The separate eight-unit reservation changes availability, not book on-hand; B agreement does not reconcile A/C/D.'],'Retain40 book units and distinguish canceled demand from completed custody movements.')
add(6,'Is B available book stock32 after its separate active eight-unit reservation?', ['R03','J03','BIN03','J01','K03'],['Availability equals book minus applicable nonoverlapping status deductions. Reservation remains internal allocation.'],['B book balance is40. BIN03 identifies eight reserved B units still on shelfB2, distinct from both the dispatched cartons and canceled request, and still active at cutoff.','The applicable status deduction is eight units, giving40-8=32 available. The A quarantine has no B effect.'],'proved',[pr('claim06','Audit.availableB = 32')],['Reserved units remain physically/book on hand; this does not establish shipment to the next-day customer.'],'Retain32 available and40 book units with the eight-unit reservation separately shown.',['Use the R03/BIN03 applicable finite status schedule; no undocumented B quarantine or extra reservation is introduced.'])
add(7,'Did the A customer accept48 units while the warehouse separately accepted a12-unit return before cutoff?', ['T03','R01','R02','J02','M02','K01'],['Four full crates convert to48 units; one full crate to12. Customer delivery and warehouse return are distinct custody stages.'],['T03/J02/M02 say five crates departed, customer accepted four, and the still-sealed fifth was returned and accepted by Elin inside the cage at16:00.','Customer acceptance is4×12=48; warehouse return acceptance is1×12=12.','All departing crates have a documented later disposition, but the original five-crate order was not fully delivered to the customer.'],'proved',[pr('claim07','Audit.deliveredA = 48 ∧ Audit.returnedA = 12')],['A closed custody chain is not equivalent to full customer delivery; the return does not erase the original departure.'],'Retain the two stage-specific quantities and signatory roles.')
add(8,'Was only12 of the original18 requested B units delivered, so the original order was not fully delivered despite all handed-over cartons arriving?', ['T04','R01','R02','J03','M03'],['The denominator for full original-order delivery is requested quantity, not merely the smaller actual handoff. Requests/cancellations do not move stock.'],['The request was three cartons=18; signed actual handoff and customer confirmation cover two full cartons=12.','The third carton remained at the warehouse and was canceled, not returned or secretly replaced.','12<18 proves the original order was not fully delivered. This is consistent with every actually dispatched carton being delivered.'],'proved',[pr('claim08','Audit.requestedB = 18 ∧ Audit.deliveredB = 12 ∧ Audit.deliveredB < Audit.requestedB')],['The finding does not allege carrier loss or customer return; it compares clearly identified stages and denominators.'],'Retain the incomplete-original-order conclusion and clarify that dispatched goods were all delivered.')
add(9,'Do the supplied equally authoritative A count sheets record contradictory totals148 and147 for the same lot, scope and18:00 cutoff?', ['N01','N02','N03','N04','R03','R04','BIN04'],['Equal-authority same-scope observations remain competing evidence without a recount/authorized correction; journal arithmetic and filename order confer no priority.'],['N01 attributes148 to Elin and N02 attributes147 to Tomas at the same cutoff, lot and boundary, both including quarantine and return cage.','The exact integer totals differ by one; the loose-sleeve margin note does not revise the signed total. No reconciliation/recount/cancellation is supplied.','The report claims only that the supplied counts conflict, which is directly supported. The formal theorem concerns attributed records, not simultaneous contradictory physical totals.'],'proved',[pr('claim09','Audit.elinCount.lot = Audit.reedCount.lot ∧ Audit.elinCount.scope = Audit.reedCount.scope ∧ Audit.elinCount.cutoff = Audit.reedCount.cutoff ∧ Audit.elinCount.issuer ≠ Audit.reedCount.issuer ∧ Audit.elinCount.amount = 148 ∧ Audit.reedCount.amount = 147 ∧ Audit.elinCount.amount ≠ Audit.reedCount.amount')],['The true physical A count remains unresolved. Supported evidence-of-conflict is not the same semantic claim as asserting one physical total.'],'Retain both attributed observations and request a recount/signed reconciliation without choosing by book agreement.',['Count signatures and scope labels are accepted as supplied documentary attributions, not infallible world-state facts.'])
add(10,'Does the imported C signed ledger compute minus one from opening zero, outbound nine and inbound eight?', ['J04','R03','BIN04'],['Book arithmetic is signed integer arithmetic; lots cannot offset each other. A negative ledger result does not describe negative physical objects or prove a correct repair.'],['J04 gives imported opening0, posting-9 at10:10 and posting+8 at10:20.','Exact signed calculation0-9+8=-1 preserves the recorded anomaly rather than truncating tozero or adding another lot.','The report carefully says imported book balance, so it is supported without a C physical count.'],'proved',[pr('claim10','Audit.importedC = -1')],['No physical shortage, fraud, destruction, unit-mapping correction or adjustment amount is established.'],'Retain the imported minus-one anomaly and seek the original mapping plus an authorized correction.',['The theorem assesses the supplied imported postings as written; it does not certify their original business correctness.'])
add(11,'Does the supplied D packet leave actual accepted quantity unresolved, with a blank receiver signature and competing provisional74/78 proposals?', ['T05','M01','M04','K04','BIN05','R04'],['A guessed/legible planned numeral is not a signed actual acceptance. D lacks complete custody evidence; unsigned proposals and absent photographs do not settle the event.'],['The original page5 was visually inspected: lot/ticket identity and blank receiver acceptance are clear; the pale bottom quantity appears compatible with78 but is not used as an accepted amount.','M01 supplies tentative receiver74 and carrier78, neither an authenticated correction. M04/BIN05 provide no original carbon copy, supplied recount or completed evidence response.','Possible completed histories with74 or78 accepted preserve the same unsigned supplied evidence. The auxiliary theorem demonstrates nonuniqueness without asserting either value or limiting all possible outcomes to those two.','Thus the report\'s evidence-limit claim is supported. Its unsigned statement is read as referring to the supplied acceptance box, not an assertion about all possible records elsewhere.'],'auxiliary',[pr('claim11Alternatives','Audit.possibleD74.suppliedReceiverSigned = false ∧ Audit.possibleD78.suppliedReceiverSigned = false ∧ Audit.possibleD74.receiverProposal = Audit.possibleD78.receiverProposal ∧ Audit.possibleD74.carrierProposal = Audit.possibleD78.carrierProposal ∧ Audit.possibleD74.actualAccepted ≠ Audit.possibleD78.actualAccepted','auxiliary')],['No actual D accepted quantity, failed shipment, forgery or short-shipping conclusion follows. Visual uncertainty and missing event authority are distinct limits.'],'Retain unresolved accepted quantity and obtain an authenticated acceptance record and missing recount evidence.',['The proposed74/78 quantities are evidence of proposals only. The auxiliary completions are hypothetical, not a transcription of the pale field as fact.'])
add(12,'Is supplied movement completeness explicitly restricted to A andB for the stated day, without comparable completeness forD?', ['K03','R04','J01','J03','BIN05'],['Completeness is a named domain/date/evidence-type assertion and must not expand from movements into physical reconciliation or other lots.'],['K03/R04 explicitly certify all A/B movements within that day and explicitly deny extending that status toD.','The finite documented completeness list therefore contains A/B and excludesD.','This supports exact A/B book arithmetic but leaves A physical conflict and C/D unresolved matters visible.'],'proved',[pr('claim12','Audit.Lot.A ∈ Audit.completeMovementLots ∧ Audit.Lot.B ∈ Audit.completeMovementLots ∧ Audit.Lot.D ∉ Audit.completeMovementLots')],['Exclusion from a completeness declaration is not evidence that no D movement occurred or that every other warehouse fact is unreliable.'],'Retain the bounded A/B-day coverage statement.',['The finite list encodes the source\'s scope assertion, not an independently verified completeness theorem about real records.'])
add(13,'Under the supplied stock rules, does a reservation alter allocation while leaving boundary-crossing book stock unchanged?', ['R02','R03','J03','BIN03'],['R02 distinguishes reservation/request from custody movement; R03/BIN03 make reservation an internal availability deduction.'],['R02 explicitly says a reservation does not move inventory merely by existing; R03 defines its internal-status role.','BIN03 supplies the concrete B example: eight units remain physically on shelfB2, with no departure/delivery or physical absence.','The modeled reservation transition changes the reserved field while preserving on-hand for any represented state, supporting the report\'s rule-level claim.'],'proved',[pr('claim13','∀ s q, (Audit.reserve s q).onHand = s.onHand ∧ (Audit.reserve s q).reserved = s.reserved + q')],['The invariant does not authorize arbitrary reservation quantities or imply that every physical action called a reservation outside this fictional rule is movement-free.'],'Retain and keep reservation allocation separate from actual shipment.')
add(14,'Does the supplied packet lack an approved correction resolving the C import anomaly, despite an unsigned proposal and evidence request?', ['J04','BIN04','R03'],['An unsigned hypothesis or request is not an authorized correction. The claim is about supplied evidence only, not all records that could exist elsewhere.'],['J04 explicitly records a possible carton/unit error as an unsigned proposal and says no approved correction is supplied.','BIN04 records an outstanding request for original mapping and no approved correction amount. No other supplied source resolves it.','The finite evidence list therefore contains a proposal and lacks approved correction, supporting the exact scoped report assertion.'],'proved',[pr('claim14','Audit.CorrectionEvidence.unsignedProposal ∈ Audit.suppliedCCorrections ∧ Audit.CorrectionEvidence.approvedCorrection ∉ Audit.suppliedCCorrections')],['This does not prove an approved correction never existed elsewhere, or that a proposed mapping explanation is false. The correct repair amount is unknown.'],'Retain the support gap and await original mapping plus authorized correction.',['The no-approved-correction statement is scoped to the complete supplied packet, not historical universality.'])
def readable(s):return re.sub(r'(?<=[a-z])(?=[0-9])',' ',s)
for item in f:
 for field in ('question','recommendation'):item[field]=readable(item[field])
 for field in ('rules','assumptions','reasoning','limits'):item[field]=[readable(x) for x in item[field]]
